INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1027, '数学', '三年级', '计算', 2, '{"stem": "用竖式计算：58÷4=", "options": null}', '14……2', '58=40+18，40÷4=10，18÷4=4 余 2，10+4=14，所以 58÷4=14……2。（竖式：十位 5÷4 商 1 余 1 个十，个位 18÷4 商 4 余 2）', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p075.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
