INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 2, '{"stem": "一本故事书有 67 页，小军每天看 7 页，多少天后这本书还剩 4 页没有看？", "options": null}', '9天', '先求 9 天前共看了多少页：67-4=63（页）；每天看 7 页，63÷7=9（天）。答：9 天后这本书还剩 4 页没有看。', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p076.png"]', 0);

