INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 2, '{"stem": "小宇有 15 个空的糖盒，将 45 颗糖每 5 颗放一盒，他的糖盒够用吗？若有剩余，还剩下几个空的糖盒？", "options": null}', '够用，还剩6个', '45÷5=9（个），装 45 颗糖需要 9 个糖盒；9<15，所以糖盒够用；还剩下 15-9=6（个）空的糖盒。', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p076.png"]', 0);
